import{_ as e,o as s,c as n,ag as t}from"./chunks/framework.PVHj0As1.js";const o="/pub-blog/assets/image-20250105215428087.Bn3x-9aF.png",r="/pub-blog/assets/image-20250105215450332.BHZUlxgJ.png",i="/pub-blog/assets/image-20250105215510702.B0A4xqZX.png",p="/pub-blog/assets/809751228.07WsbXI3.jpg",E="/pub-blog/assets/image-20250105220257474.Ezx37Pp1.png",l="/pub-blog/assets/image-20250105220425473.AVTBiGLb.png",g="/pub-blog/assets/image-20250105220833428.BvK3nCNX.png",A="/pub-blog/assets/image-20250105220935126.b4twionm.png",d="/pub-blog/assets/image-20250105221028989.CXXbt4yR.png",m="/pub-blog/assets/image-20250105221118340.SLWPSeub.png",c="/pub-blog/assets/image-20250105221414179.DWekNeOY.png",h="/pub-blog/assets/image-20250105221436893.DoZ7VpHF.png",B="/pub-blog/assets/image-20250105221540729.ZAA2Mnei.png",b="/pub-blog/assets/image-20250105221558679.B-TJDrtH.png",k=JSON.parse('{"title":"3 分钟教你使用 MarsCode AI 生成在线图表","description":"","frontmatter":{},"headers":[],"relativePath":"前端技能/3分钟教你使用MarsCode AI 生成在线图表/3分钟教你使用MarsCode AI 生成在线图表.md","filePath":"前端技能/3分钟教你使用MarsCode AI 生成在线图表/3分钟教你使用MarsCode AI 生成在线图表.md","lastUpdated":1736220086000,"__rawMarkdown":"# 3 分钟教你使用 MarsCode AI 生成在线图表\\n\\n## 需求\\n\\n对于前端开发者来讲，应该必不可少的会碰到开发在线图表的需求。国内开发者要开发在线图表应该都绕不过[echarts](https://echarts.apache.org/zh/index.html)\\n\\n对于很多刚上手 echart 的小伙伴来说，查阅配置文档是一个很痛苦的事情。\\n\\n## 上手 echarts\\n\\n一般上手 echarts 的步骤如下\\n\\n1. [查看快速上手教程](https://echarts.apache.org/handbook/zh/get-started/)\\n\\n   ![image-20250105215428087](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105215428087.png)\\n\\n2. [查阅示例，选择想要的图表](https://echarts.apache.org/handbook/zh/get-started/)\\n\\n   ![image-20250105215450332](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105215450332.png)\\n\\n3. [根据实际需求，查阅配置项，进行微调](https://echarts.apache.org/zh/option.html)\\n\\n   ![image-20250105215510702](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105215510702.png)\\n\\n4. 各种尝试代码，验证结果\\n\\n   ![img](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/809751228.jpg)\\n\\n## MarsCode AI 介绍\\n\\nMarsCode AI 是豆包旗下的智能编程助手，提供以智能代码补全为代表的核心能力，支持主流编程语言及 IDE，能在编码过程中提供单\\n\\n行或整个函数的建议，同时支持在用户编码过程中提供代码解释、单测生成、问题修复、技术问答等辅助功能，提升编码效率与质量。\\n\\n当前 MarsCode AI 提供了以下功能：\\n\\n1. 代码补全 Code Completion\\n2. 代码解释 Code Explain\\n3. 单测生成 Unit Test Generation\\n4. 注释生成 Generate documentation\\n5. 智能修复 AI Fix\\n6. 智能问答 AI Q&A\\n7. **智能问答 AI Q&A 一键 Apply AI 生成的代码变更至项目对应的文件位置并形成 Diff**\\n\\n当前要体验的便是 **一键 Apply AI 生成的代码变更至项目对应的文件位置并形成 Diff** 功能。\\n\\n> 当前该功能该功能目前仅支持 VSCode（需升级至 **1.1.42** 版本）\\n\\n## vs code 安装 MarsCode AI\\n\\n首次安装\\n\\n1. 打开 vscode 左侧的插件列表\\n2. 搜索关键字 **MarsCode AI**\\n3. 点击安装\\n\\n![image-20250105220257474](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105220257474.png)\\n\\n4. 首次安装成功后，使用的话需要登录\\n\\n5. 然后，在 vscode 的左侧便可以看到 ai 助手\\n\\n   ![image-20250105220425473](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105220425473.png)\\n\\n## MarsCode AI 生成代码并且应用\\n\\n1. 使用 vscode 打开你的工程目录，我这里是空的文件夹\\n\\n2. 然后进行对话，输入你的需求\\n\\n   ```\\n   请根据2011-2024年中国程序员的数量，使用echarts把数据渲染出来。需求如下：\\n   1. 所有的代码都写入到一个html文件中\\n   2. 一个文件中 ，请使用不同的图表如柱状图、饼图和折线图显示出来数据\\n   ```\\n\\n3. 此时 **MarsCode AI ** 便开始生成代码\\n\\n   ![image-20250105220833428](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105220833428.png)\\n\\n4. 这个时候，可以点击 右上角的 **Apply** 按钮，便可以把当前代码应用到对应的文件上，如果该文件还没有创建，那么便会自动的创建\\n\\n   ![image-20250105220935126](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105220935126.png)\\n\\n5. 这里，你可以根据需求，点击 **全部采纳** 或者**部分采纳**\\n\\n   > ​ 我们点击 **全部采纳**\\n\\n   ![image-20250105221028989](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105221028989.png)\\n\\n6. 实际效果\\n\\n   ![image-20250105221118340](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105221118340.png)\\n\\n## 继续调整\\n\\n可以看到，**MarsCode AI** 基本实现了我们的需求，这个时候发现部分效果不合适\\n\\n1. 文字遮挡了\\n2. 希望图片水平排列\\n\\n我们继续对话让它进行调整\\n\\n![image-20250105221414179](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105221414179.png)\\n\\n---\\n\\n再次点击 **Apply**\\n\\n![image-20250105221436893](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105221436893.png)\\n\\n---\\n\\n此时，你可以根据需求 点击 **全部采纳** 或者 **采纳**\\n\\n![image-20250105221540729](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105221540729.png)\\n\\n得到效果\\n\\n![image-20250105221558679](3%E5%88%86%E9%92%9F%E6%95%99%E4%BD%A0%E4%BD%BF%E7%94%A8MarsCode%20AI%20%E7%94%9F%E6%88%90%E5%9C%A8%E7%BA%BF%E5%9B%BE%E8%A1%A8.assets/image-20250105221558679.png)\\n\\n---\\n\\n但是我们发现，第一个柱状图还是出现了文字遮挡，这里继续对话调整即可\\n\\n---\\n\\n## 总结\\n\\n经过简单的小案例，我们发现豆包的交互还是比较智能的，包括 ui 的设计，对话的便利性\\n\\n但是也存在缺点，如生成代码时反应慢、没有提供批量编辑或者创建文件的功能。代码质量也有待提升\\n\\n**“本文正在参加豆包 MarsCode** **AI** **编程体验家活动”**\\n"}'),C={name:"前端技能/3分钟教你使用MarsCode AI 生成在线图表/3分钟教你使用MarsCode AI 生成在线图表.md"};function _(I,a,F,u,M,D){return s(),n("div",null,[...a[0]||(a[0]=[t("",41)])])}const x=e(C,[["render",_]]);export{k as __pageData,x as default};
